-- The Swiss desktop's colours (colors/swiss.lua, generated by ~/.config/swiss-desktop from its tokens and linked
-- here), following the desktop's light / dark mode: the mode file swiss-mode writes is watched, so Super+Shift+T
-- switches Neovim at once. Setting 'background' makes Neovim reload the colour scheme in the other mode.
local modefile = (vim.env.XDG_STATE_HOME or (vim.env.HOME .. "/.local/state")) .. "/swiss/mode"
local watcher -- kept here so it is not collected

local function desktop_mode()
  local f = io.open(modefile, "r")
  if not f then return nil end
  local mode = f:read("*l")
  f:close()
  return (mode == "light" or mode == "dark") and mode or nil
end

local function follow()
  local mode = desktop_mode()
  if mode and vim.o.background ~= mode then vim.o.background = mode end
end

return {
  {
    "LazyVim/LazyVim",
    opts = {
      colorscheme = function()
        follow()
        vim.cmd.colorscheme("swiss")
        if not watcher then
          watcher = vim.uv.new_fs_event()
          if watcher then watcher:start(modefile, {}, vim.schedule_wrap(follow)) end
        end
      end,
    },
  },
}
